<div class="form-grid"><div class="field field-full"><label>Visit entry</label><div class="segmented-control"><label><input type="radio" name="entry_source" value="pre_registered" checked> Pre-registered</label><label><input type="radio" name="entry_source" value="walk_in"> Walk-in</label></div><small class="field-help" id="entry_source_help">Pre-register an upcoming visitor before arrival.</small></div>
<div class="field field-full"><label for="visitor_search">Visitor <span class="required">*</span></label><input id="visitor_search" type="search" autocomplete="off" placeholder="Search by name, ID, phone or email"><input type="hidden" id="visitor_id" name="visitor_id" required><div id="visitor_results" class="search-results" hidden></div><small class="field-help">Search and select an existing visitor. Registration is handled separately to avoid duplicate visitor profiles.</small><select id="visitor_id_legacy" hidden aria-hidden="true"><option value="">Select visitor</option><?php foreach($visitors as $visitor): $name=(string)($visitor['full_name']??trim((string)($visitor['first_name']??'').' '.(string)($visitor['last_name']??'')));?><option value="<?=e((string)($visitor['id']??''))?>" <?=((int)($visitor['id']??0)===$preselectedVisitor)?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></div>
