<div class="field"><label for="department_id">Department</label><select id="department_id" name="department_id"><option value="">No department</option><?php $selectedDepartment=(string)oldOr('department_id',$currentDepartmentID!==null?(string)$currentDepartmentID:'');foreach($departments as $department):$did=(int)($department['id']??0);?><option value="<?=e((string)$did)?>" <?=($selectedDepartment===(string)$did)?'selected':''?>><?=e((string)($department['name']??''))?></option><?php endforeach;?></select><?php if($currentDepartmentID):?><small class="field-help">Preselected from your user department.</small><?php endif;?></div>
