</div><div class="form-actions"><a class="btn btn-secondary" data-back href="<?=e(url('visits.php'))?>">Cancel</a><button class="btn btn-primary" type="submit" data-loading-label="Creating..."><span data-button-label>Create visit</span></button></div>
</form>
<script>
(()=>{const search=document.getElementById('visitor_search'),id=document.getElementById('visitor_id'),results=document.getElementById('visitor_results'),legacy=document.getElementById('visitor_id_legacy');let timer,seq=0;const pick=v=>{id.value=v.id;search.value=v.full_name||('Visitor #'+v.id);results.hidden=true;results.innerHTML='';};const run=async()=>{const q=search.value.trim();if(q.length<2){results.hidden=true;return}const current=++seq;try{const r=await fetch('/api/v1/visitors?q='+encodeURIComponent(q)+'&limit=10',{headers:{Accept:'application/json'}});const data=await r.json();if(current!==seq)return;const items=data.items||data.data?.items||[];results.innerHTML='';items.forEach(v=>{const b=document.createElement('button');b.type='button';b.className='search-result';b.textContent=(v.full_name||'Visitor')+(v.id_number?' • '+v.id_number:'')+(v.phone?' • '+v.phone:'');b.onclick=()=>pick(v);results.appendChild(b)});results.hidden=!items.length}catch(_){results.hidden=true}};search.addEventListener('input',()=>{id.value='';clearTimeout(timer);timer=setTimeout(run,250)});legacy.addEventListener('change',()=>{const o=legacy.selectedOptions[0];if(o&&o.value)pick({id:o.value,full_name:o.textContent})});})();
</script>